def transform(grid):
    H=len(grid); W=len(grid[0]); lines={}
    for i,r in enumerate(grid):
        if r[0]!=0 and all(x==r[0] for x in r): lines.setdefault(r[0],[]).append(i)
    o=[[0]*W for _ in range(H)]
    for i,r in enumerate(grid):
        if any(i in v for v in lines.values()): o[i]=r[:]
    for i,r in enumerate(grid):
        for j,c in enumerate(r):
            if c and c in lines and not any(i in v for v in lines.values()):
                for k in lines[c]:
                    d=k-1 if i<k else k+1
                    if 0<=d<H:o[d][j]=c
    return o
